/d84294b5-aaec-4547-8bc1-48f656cb1af9.png","optimized":"covers/optimized-v1/0b3e00b3a2f760eb51d99fb7.webp"},{"original":"covers/import-20261021/e3dc914e-78ab-4490-a147-fc73ea8a4b39.png","optimized":"covers/optimized-v1/f1dbd47a0cec7ed45ce58942.webp"},{"original":"covers/import-20261021/eb4d185c-b5c3-4cc0-92df-d79df8234af0.png","optimized":"covers/optimized-v1/440f3c600bbdb737139109cc.webp"}]'::jsonb;
begin
  -- Ambientes novos não têm essas capas nem suas referências de produção.
  if not exists (
    select 1 from public.journey_steps s, jsonb_to_recordset(mapping) as m(original text, optimized text)
    where m.original in (s.cover_path, s.cover_path_light, s.cover_path_dark)
  ) then return; end if;

  if not exists (select 1 from storage.buckets where id = 'journey-content' and not public) then
    raise exception 'O bucket de capas deve continuar privado';
  end if;
  if exists (
    select 1 from jsonb_to_recordset(mapping) as m(original text, optimized text)
    where not exists (select 1 from storage.objects o where o.bucket_id = 'journey-content' and o.name = m.optimized)
  ) then raise exception 'Upload das capas otimizadas ainda não está completo'; end if;

  update public.journey_steps s set
    cover_path = coalesce((select m.optimized from jsonb_to_recordset(mapping) as m(original text, optimized text) where m.original = s.cover_path), s.cover_path),
    cover_path_light = coalesce((select m.optimized from jsonb_to_recordset(mapping) as m(original text, optimized text) where m.original = s.cover_path_light), s.cover_path_light),
    cover_path_dark = coalesce((select m.optimized from jsonb_to_recordset(mapping) as m(original text, optimized text) where m.original = s.cover_path_dark), s.cover_path_dark)
  where exists (
    select 1 from jsonb_to_recordset(mapping) as m(original text, optimized text)
    where m.original in (s.cover_path, s.cover_path_light, s.cover_path_dark)
  );
end;
$covers$;
